            notebooks.append({
                "id": nb_id,
                "path": nb_path,
                "title": item[1],
                "timestamp": item[2][0] if item[2] else 0,
                "source_count": item[3] if len(item) > 3 else 0,
            })
    except (IndexError, TypeError):
        pass
    return sorted(notebooks, key=lambda x: x["source_count"], reverse=True)

