def _python_type_to_json_schema(t: type) -> Dict[str, str]:
    """Convert a Python type hint to a JSON Schema type."""
    type_map = {
        str: {"type": "string"},
        int: {"type": "integer"},
        float: {"type": "number"},
        bool: {"type": "boolean"},
        list: {"type": "array"},
        dict: {"type": "object"},
    }
    # Handle Optional[X] → X with nullable
    origin = getattr(t, "__origin__", None)
    if origin is type(None):
        return {"type": "null"}
    return type_map.get(t, {"type": "string"})

def get_client(self):
    """
    Return a ``lmstudio.LMStudio`` SDK client instance.

    The SDK client is lazy-imported so that the rest of the codebase
    does not require the ``lmstudio`` package at import time.

    Raises:
        ImportError if the ``lmstudio`` package is not installed.
    """
    try:
        import lmstudio as lms
    except ImportError as exc:
        raise ImportError(
            "lmstudio package not installed.  "
            "Run: pip install lmstudio"
        ) from exc
    return lms.LMStudio(base_url=self._base_url)

def text_to_speech(
    self,
    text: str,
    voice: str = "Kore",
    model: str = "gemini-2.5-flash-preview-tts",
    output_path: Optional[str] = None,
) -> bytes:
    """Convert text to speech using Gemini TTS.

    Args:
        text: Text to synthesize.
        voice: Voice name. Options include: Aoede, Charon, Fenrir, Kore,
            Orus, Puck, Leda, Zephyr, etc.
        model: TTS model name.
        output_path: Optional path to save the audio file to.

    Returns:
        Raw audio bytes. If output_path is given, also saves to file.
    """
    body: Dict[str, Any] = {
        "contents": [{"parts": [{"text": text}], "role": "user"}],
        "generationConfig": {
            "responseModalities": ["AUDIO"],
            "speechConfig": {
                "voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice}}
            },
        },
    }
    result = self._rest_request("POST", f"models/{model}:generateContent", data=body)

    audio_data = b""
    for candidate in result.get("candidates", []):
        for part in candidate.get("content", {}).get("parts", []):
            if inline_data := part.get("inlineData", {}):
                import base64
                audio_data = base64.b64decode(inline_data.get("data", ""))
                break

    if output_path and audio_data:
        out = Path(output_path)
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_bytes(audio_data)
        logger.info("TTS saved to %s (%d bytes)", output_path, len(audio_data))

    return audio_data

def stream_code_assistant_offline_generation(
    self, request: Dict[str, Any]
) -> Iterator[str]:
    """Stream an offline code assistant generation (StreamCodeAssistantOfflineGeneration).

    Args:
        request: Code assistant request payload.

    Yields:
        Text chunks as they stream.
    """
    endpoint = f"{GRPC_BASE}/StreamCodeAssistantOfflineGeneration"
    headers = {**self._headers(), "Accept": "text/event-stream"}
    with self._session.post(
        endpoint, json=request, headers=headers, stream=True, timeout=120
    ) as resp:
        resp.raise_for_status()
        for line in resp.iter_lines(decode_unicode=True):
            if line.startswith("data: "):
                data_str = line[6:]
                if data_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(data_str)
                    if text := chunk.get("text"):
                        yield text
                except json.JSONDecodeError:
                    continue

